// Copies the compiled ABIs out of the contracts package as TS `as const`,
// which is what viem/wagmi need for full type inference on calls and events.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const here = import.meta.dirname;
const artifacts = resolve(here, '../../contracts/artifacts/src');

const contracts = [
  { name: 'Marketplace', export: 'marketplaceAbi' },
  { name: 'MarketplaceCollection', export: 'collectionAbi' },
  { name: 'CollectionFactory', export: 'factoryAbi' },
];

const parts = [
  '// GENERATED by scripts/generate-abi.mjs — do not edit by hand.',
  '// Regenerate after changing the contracts: pnpm abi',
  '',
];

for (const contract of contracts) {
  const path = `${artifacts}/${contract.name}.sol/${contract.name}.json`;

  let parsed;
  try {
    parsed = JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    console.error(
      `Could not read ${path}\nRun \`pnpm compile\` in the repo root first.`,
    );
    process.exit(1);
  }

  parts.push(
    `export const ${contract.export} = ${JSON.stringify(parsed.abi, null, 2)} as const;`,
    '',
  );
  console.log(`  ${contract.name}: ${parsed.abi.length} ABI entries`);
}

writeFileSync(resolve(here, '../lib/abi.ts'), parts.join('\n'));
console.log('wrote lib/abi.ts');
